) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_polish_ci;

--
-- Zrzut danych tabeli `news_articles`
--

INSERT INTO `news_articles` (`id`, `slug`, `title`, `summary`, `content`, `category`, `published_at`) VALUES
(1, 'Premiera bardzo oczekiwanej gry', 'Gta VI WYCHODZI!!!!', 'Wyszło to po  4 latach oczekiwania', 'Szósta główna część niezwykle popularnej serii gier akcji z otwartym światem, nad którą czuwa firma Rockstar Games. GTA 6 zostało osadzone w mieście Vice City i okolicach, pozwalając wcielić się w parę bohaterów: Jasona i Lucię.', 'Premiery', '2026-11-19 10:15:49'),
(2, 'aktualizacja-gry-przyklad', 'Aktualizacja gry — jak czytać listę zmian?', 'Przykładowy wpis o notatkach do aktualizacji i informacjach, na które warto zwrócić uwagę.', 'Na liście zmian poszukaj informacji o poprawkach wydajności, zmianach balansu i znanych problemach. Jeśli wracasz po dłuższej przerwie, zacznij od podsumowania największych zmian.\n\nTo przykładowy artykuł GameZone. W jego miejsce możesz dodać opis rzeczywistej aktualizacji.', 'Aktualizacje', '2026-11-19 10:15:49'),
(3, 'zapowiedz-gry-przyklad', 'Co można wyczytać ze zwiastuna gry?', 'Przykładowy wpis o zapowiedziach i różnicy między zwiastunem a pokazem rozgrywki.', 'Zwiastun filmowy buduje klimat, ale nie zawsze pokazuje, jak faktycznie wygląda rozgrywka. Jeśli interesuje Cię sterowanie, interfejs albo walka, poszukaj dłuższego nagrania z gry.\n\nTo przykładowy artykuł GameZone. W jego miejsce możesz dodać własną zapowiedź.', 'Zapowiedzi', '2026-11-19 10:15:49');

