--
-- Struktura tabeli dla tabeli `reviews`
--

CREATE TABLE `reviews` (
  `id` int(11) NOT NULL,
  `game_id` int(11) NOT NULL,
  `author` varchar(100) NOT NULL,
  `user_id` int(11) NOT NULL,
  `content` text NOT NULL,
  `rating` decimal(3,1) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_polish_ai_ci;

--
-- Zrzut danych tabeli `reviews`
--

INSERT INTO `reviews` (`id`, `game_id`, `author`, `user_id`, `content`, `rating`, `created_at`) VALUES
(1, 1, 'Krzys', 0, 'Elden Ring to świetna gra, która potrafi wciągnąć na długie godziny., świat jest ogromny, a walka z bossami daje dużo satysfakcji po wielu trudach. Grafika i klimat są imponujące. Gra nie należy do najłatwiejszych, ale po kilku próbach albo rozwalony jest kontroler, albo boss pada. Zdecydowanie polecam każdemu, kto lubi wyzwania i gry z otwartym światem.\r\nP.S.\r\nPlusem jest, że gracz nie jest ciągnięty za rączkę przez cała grę lecz sam odkrywa świat Elden Ring.', 9.5, '2026-10-22 05:28:50'),
(2, 2, 'H3rbatka_', 0, 'Bardzo fajna gra mozna robic duzo fajnych rzeczy jak sie chce fajne buildy fajne samochody tylko brakuje mi ciekawszych opcji customizowania samochodow troche. historia wysmienita i postacie tez tylko wkurza mnie ta panam bierze mnie na jakas samobojcza misje i potem ja musze odwalac cala brudna robote a ona tylko cos pierdzi ze uwaga snajper a jak jej odmowie to robi sceny.', 9.0, '2026-10-22 05:28:50'),
(3, 6, '☣ RUZG4R', 0, 'niesamowitą fabułę, przepiękną grafikę i ♥♥♥♥♥♥♥♥♥♥ dopracowany system walki. Każda walka z bossem dostarcza ogromnych emocji, a historia Kratosa i Atreusa potrafi naprawdę poruszyć. Świat gry jest ogromny, pełen sekretów, ciekawych postaci i epickich przygód. Do tego świetna muzyka i klimatyczne lokacje sprawiają, że można się całkowicie zatracić w rozgrywce.\r\n\r\nJak dla mnie jedna z najlepszych gier, w jakie miałem okazję zagrać. Zdecydowanie polecam każdemu fanowi gier akcji i mocnych historii. Prawdziwe arcydzieło, które zasługuje na solidne 9.6/10! 🔥🐺', 9.6, '2026-10-22 05:28:50'),
(4, 7, 'kzdunek', 0, 'Fantastyczny świat razem z dobrze napisanymi postaciami bardzo klimatyczna grafika bardziej realistyczna niż w oryginale dodatki jedne z najbardziej wciągających fabularnie rozgrywka bardzo przyjemna ale trochę powtarzalna.', 9.5, '2026-10-22 08:03:14'),
(5, 3, 'kabanos', 0, 'dobrze sie gra fajne zmiany na plus ten dynamiczny overal, the grounds też dobry tryb nowy i pierwszy raz w historii w ea fc.', 8.0, '2026-10-22 08:13:54'),
(6, 5, 'Piter06041', 0, 'Bardzo bardzo fajna gra mega polecam jak ktoś interesuje się samochodami i motoryzacją mi gra mega siedzi i warto kupić najlepiej na przecenie. Powodzenia w graniu\r\n', 9.2, '2026-10-22 08:20:05'),
(7, 4, 'Widiusz', 0, 'Wreszcie Civka, która wkręciła mnie równie mocno jak część pierwsza. :)\r\n1.Dodanie mechaniki dzielnic oraz możliwość budowy cudów tylko w określonych lokalizacjach bardzo urozmaiciło rozgrywkę wybijając gracza z monotonnego klikania budowy wszystkiego w każdym mieście.\r\n\r\n2.Bardzo duży plus jeśli chodzi o mechanikę religii w grze. Mając swoją religię odpowiednio skonfigurowaną można wypracować dużą przewagę nad graczami, którzy swojej nie rozwinęli. Świetnie pomyślany pomysł misjonarzy/apostołów oraz walki duchowej. Daje to nam drugą płaszczyznę zmagań obok klasycznej walki.\r\n\r\nKreskówkowa stylistyka, krytykowana przez niektórych, mnie akurat bardzo przypadła do gustu.\r\nPodsumowując warto, nawet z samą podstawką.', 8.8, '2026-10-22 08:22:49'),
(8, 8, 'Senko', 0, 'Był to zwykły dzień...\r\n w minecraft.\r\n>Bądź mną\r\n>obudź się \r\n>coś ci syczy\r\n>Okurła.jpg\r\n>kriper\r\n>mam świat na hardcorze od 5 lat\r\n>Domyśl sie', 9.6, '2026-10-22 08:36:48'),
(9, 9, 'to_nie_Sał*tka', 0, 'sper gra dosfalem za drmo robale za kompiejk polecum', 10.0, '2026-10-22 08:47:27'),
(10, 10, 'Senko', 0, 'Mayano to moja waifu i nikt nie będzie hejtował mojego ukochanego lotniczego karła + mommy creek pls give milk.', 8.9, '2026-10-22 09:08:07'),
(11, 11, 'spocynymaciuś123', 0, 'Ta gra jest okropna!!! Grają w nią same spocuchy cuchnące nie wychodzące z pokoju 24/7 ALE pieniądze które zostawiłem w tej grze już nigdy nie wrócą :( liczba pieniędzy spłaciła by kredyt mojej matki i ojca. Jedyna rzecz ktgóra trzyma mnie w tej grze tyo moje wydane pieniądze na skin. ', 7.6, '2026-10-22 09:19:37'),
(12, 9, 'Cirno', 1, 'spotkałem sałatke na multiplayerze, mam teraz depresje', 1.0, '2026-10-29 09:11:22'),
(13, 10, 'Cirno', 1, 'PETA MÓWI ŻE TO KRZYWDZENIE ZWIERZĄT!!!!!! DO DIAŁBA Z NIMI DAJCE 500ZŁ RYDZYKOWI NA RADIO MARYJA', 1.0, '2026-11-02 09:06:39'),
(14, 11, 'Relakaler', 5, 'małe dziecko zgwałciło księdza', 1.0, '2026-11-09 11:42:56'),
(15, 10, 'Relakaler', 5, 'Koń zwalił mi człowieka', 3.0, '2026-11-09 11:43:07'),
(16, 4, 'Relakaler', 5, 'Niewolnicztwo', 8.0, '2026-11-09 11:43:18'),
(17, 9, 'Relakaler', 5, 'Sałatka się zjebał z klifu', 10.0, '2026-11-09 11:43:32'),
(18, 3, 'Relakaler', 5, 'EA to gówno', 1.0, '2026-11-09 11:43:44'),
(19, 11, 'TomaszPerła', 7, 'ZAJEBAL MNIE PIERDOLONY CFEL WIEKU 9 LAT.\r\nWyruchalem mu potem matke i psa 10/10', 10.0, '2026-11-21 10:41:22');

